def binary_search(arr, target):
    lo, hi = 0, len(arr) - 1
    result = -1
    while lo <= hi:
        mid = (lo + hi) // 2
        if arr[mid] == target:
            result = mid
            hi = mid - 1  # continue left
        elif arr[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return result
